class Program {
    static class IntList {
        private final int[] data = new int[3];
        private int size;
        boolean add(int value) {
            if (size == data.length) return false;
            data[size++] = value;
            return true;
        }
        boolean removeFirst(int value) {
            int i = 0;
            while (i < size && data[i] != value) i++;
            if (i == size) return false;
            for (int j = i; j < size - 1; j++) data[j] = data[j + 1];
            data[--size] = 0;
            return true;
        }
        String contents() {
            return java.util.Arrays.toString(java.util.Arrays.copyOf(data, size));
        }
    }
    public static void main(String[] args) {
        IntList values = new IntList();
        values.add(4); values.add(7); values.add(4);
        System.out.println(values.add(9));
        values.removeFirst(4);
        System.out.println(values.contents());
    }
}
